//! Payloads produced by the real Laravel encrypter (`fixtures/vectors.json`, regenerated by
//! `scripts/generate_vectors.php`), decrypted with this crate.

use base64::engine::general_purpose::STANDARD;
use base64::Engine as _;
use laravel_rust_encryption::{Cipher, Encrypter, Value};
use serde_json::Value as Json;

fn b64(s: &str) -> Vec<u8> {
    STANDARD.decode(s).expect("valid base64 in fixture")
}

fn fixtures() -> Json {
    let data = std::fs::read_to_string(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/fixtures/vectors.json"
    ))
    .expect("read fixtures/vectors.json");
    serde_json::from_str(&data).expect("parse fixtures/vectors.json")
}

fn key(fx: &Json, field: &str, cipher: Cipher) -> Vec<u8> {
    let key = b64(fx[field].as_str().unwrap());
    key[..cipher.key_size()].to_vec()
}

fn encrypter(fx: &Json, cipher: Cipher) -> Encrypter {
    Encrypter::new(&key(fx, "key_b64", cipher), cipher).unwrap()
}

fn cases<'a>(fx: &'a Json, group: &str) -> &'a Vec<Json> {
    let list = fx[group]
        .as_array()
        .unwrap_or_else(|| panic!("missing {group}"));
    assert!(!list.is_empty(), "{group} is empty");
    list
}

fn cipher_of(v: &Json) -> Cipher {
    v["cipher"].as_str().unwrap().parse().unwrap()
}

#[test]
fn decrypts_laravel_encrypt_string() {
    let fx = fixtures();
    for v in cases(&fx, "vectors") {
        let enc = encrypter(&fx, cipher_of(v));
        let want = b64(v["plaintext_b64"].as_str().unwrap());
        let got = enc
            .decrypt_bytes(v["payload"].as_str().unwrap())
            .unwrap_or_else(|e| panic!("{}: {e}", v["name"]));
        assert_eq!(got, want, "{}", v["name"]);

        if let Ok(text) = String::from_utf8(want) {
            assert_eq!(
                enc.decrypt_string(v["payload"].as_str().unwrap()).unwrap(),
                text
            );
        }
    }
}

/// `Crypt::encrypt` payloads decode, and encoding the decoded value again gives PHP's
/// `serialize()` output byte for byte (floats, key order, int/string keys, binary strings).
#[test]
fn laravel_serialization_round_trips_byte_for_byte() {
    let fx = fixtures();
    for v in cases(&fx, "serialized") {
        let cipher = cipher_of(v);
        let enc = encrypter(&fx, cipher);
        let name = v["name"].as_str().unwrap();
        let want = b64(v["serialized_b64"].as_str().unwrap());

        let value = enc
            .decrypt(v["payload"].as_str().unwrap())
            .unwrap_or_else(|e| panic!("{name}: {e}"));

        let again = enc.encrypt(&value).unwrap();
        let got = enc.decrypt_bytes(&again).unwrap();

        // Both sides print the shortest digits that round-trip, but when two such strings
        // exist (17 significant digits) they may pick a different last digit. The doubles are
        // identical, so for the random sweep compare the values instead of the text.
        if name.ends_with("/float_sweep") {
            assert_eq!(enc.decrypt(&again).unwrap(), value, "{name}");
            continue;
        }

        if got != want {
            let at = got.iter().zip(&want).take_while(|(a, b)| a == b).count();
            let show = |b: &[u8]| {
                String::from_utf8_lossy(&b[at.saturating_sub(30)..(at + 30).min(b.len())])
                    .into_owned()
            };
            panic!(
                "{name}: serialization differs at byte {at}\n  rust: {}\n  php:  {}",
                show(&got),
                show(&want)
            );
        }
    }
}

#[test]
fn laravel_values_decode_to_expected_types() {
    let fx = fixtures();
    let enc = encrypter(&fx, Cipher::Aes256Cbc);
    let get = |name: &str| -> Value {
        let v = cases(&fx, "serialized")
            .iter()
            .find(|v| v["name"] == format!("aes-256-cbc/{name}"))
            .unwrap_or_else(|| panic!("no case {name}"));
        enc.decrypt(v["payload"].as_str().unwrap()).unwrap()
    };

    assert_eq!(get("null"), Value::Null);
    assert_eq!(get("true"), Value::Bool(true));
    assert_eq!(get("int_min"), Value::Int(i64::MIN));
    assert_eq!(get("int_max"), Value::Int(i64::MAX));
    assert_eq!(get("float_whole"), Value::Float(2.0));
    assert_eq!(get("float_small"), Value::Float(1.5e-7));
    assert!(
        matches!(get("float_negative_zero"), Value::Float(f) if f == 0.0 && f.is_sign_negative())
    );
    assert_eq!(get("float_inf"), Value::Float(f64::INFINITY));
    assert!(matches!(get("float_nan"), Value::Float(f) if f.is_nan()));
    assert_eq!(
        get("string_binary"),
        Value::Bytes(vec![0x00, 0xff, 0xfe, 0x80])
    );
    assert_eq!(get("string_quotes").as_str(), Some(r#"say "hi"; s:3:"x";"#));
    assert_eq!(get("empty_array"), Value::List(vec![]));
    assert_eq!(
        get("list"),
        Value::list([
            Value::Int(1),
            "two".into(),
            true.into(),
            Value::Null,
            Value::list([3, 4]),
        ])
    );

    let assoc = get("assoc");
    assert_eq!(assoc.get("user").and_then(Value::as_str), Some("alice"));
    assert_eq!(assoc.get("id").and_then(Value::as_i64), Some(7));
    assert_eq!(assoc.get("score").and_then(Value::as_f64), Some(2.5));
    assert!(assoc.get("meta").unwrap().is_null());
    // PHP key order is kept.
    let Value::Map(entries) = &assoc else {
        panic!("not a map")
    };
    let keys: Vec<_> = entries.iter().map(|(k, _)| format!("{k:?}")).collect();
    assert_eq!(keys.first().unwrap(), r#"String("user")"#);
    assert_eq!(keys.last().unwrap(), r#"String("meta")"#);

    // [1 => 'a', 0 => 'b'] is not a list: the keys are not 0..n in order.
    assert!(matches!(get("non_sequential_list"), Value::Map(_)));
    assert!(matches!(get("mixed_keys"), Value::Map(_)));
}

#[test]
fn laravel_objects_decode_without_instantiation() {
    let fx = fixtures();
    let enc = encrypter(&fx, Cipher::Aes256Cbc);
    for v in cases(&fx, "objects") {
        let value = enc.decrypt(v["payload"].as_str().unwrap()).unwrap();
        let Value::Object { class, .. } = &value else {
            panic!("expected an object, got {value:?}")
        };
        assert_eq!(class, "stdClass");
        assert_eq!(value.get("a"), Some(&Value::Int(1)));
        assert_eq!(value.get("b"), Some(&Value::list(["two"])));
        // Decode-only: it cannot be written back.
        assert!(enc.encrypt(&value).is_err());
    }
}

#[test]
fn decrypts_payloads_encrypted_with_a_previous_key() {
    let fx = fixtures();
    for v in cases(&fx, "rotated") {
        let cipher = cipher_of(v);
        let payload = v["payload"].as_str().unwrap();
        let want = b64(v["plaintext_b64"].as_str().unwrap());

        let current = encrypter(&fx, cipher);
        assert!(current.decrypt_bytes(payload).is_err(), "{}", v["name"]);

        let rotated = current
            .with_previous_keys([key(&fx, "previous_key_b64", cipher)])
            .unwrap();
        assert_eq!(
            rotated.decrypt_bytes(payload).unwrap(),
            want,
            "{}",
            v["name"]
        );
    }
}
